use serde_json::json;use std::thread;
const ID:&str="11111111-2222-4333-8444-555555555555";
fn scope(object:u64,epoch:u64)->Scope{Scope{context:app::SelectionContext{key:app::CharacterKey{source_id:7,object_id:object},epoch},channel:0}}
fn fresh_fields(s:Scope,ms:u32)->Vec<(&'static str,String)>{vec![("source_id",s.context.key.source_id.to_string()),("object_id",s.context.key.object_id.to_string()),("epoch_hex",format!("{:016x}",s.context.epoch)),("channel_id",s.channel.to_string()),("deadline_ms",ms.to_string())]}
fn witness_model()->Value{json!({"job_id":ID,"source":7,"object":10275,"selected_epoch_hex":"8000000000000200","channel_id":0,"private_registration_generation":"fedcba9876543210","effective_gear_revision_at_entry":2,"work_deadline_monotonic_nanos":1234567890,"work_operation_id":ID,"correlation_origin":"ACTUAL_REGISTERED_WORK_OPERATION_SQL_AND_RECONCILED_STORE"})}
fn job_model()->Value{let mut v=witness_model();v["state"]=json!("COMPLETE");v["epoch_hex"]=json!("8000000000000200");v["work_observed"]=json!(true);v["revision"]=json!(2);v["weapon_object"]=json!(10304);v["max_hp"]=json!(100);v["evaluated_at_millis"]=json!(1000);v["valid_until_millis"]=json!(-1);v}
#[test]fn v2_ready_and_same_Work_witness_mutants_are_strict_and_v1_stays_distinct(){
 let mut v=super::super::tests::model();v["schema"]=json!(2);v["control_contract"]=json!("NATIVE_SELECTED_WORK_CONTROL_V2");v["hold_point"]=json!("AFTER_REAL_SQL_AND_SAME_WORK_RECONCILED_STORE_BEFORE_COMMIT");v["overlap_policy"]=json!("SAME_SESSION_BUSY_UNTIL_ACTUAL_WORK_RETIRES");
 let bytes=serde_json::to_vec(&v).unwrap();assert!(decode::<Ready>(&bytes,32768).is_err());let r=decode::<Ready2>(&bytes,32768).unwrap().common().unwrap();let m=hash("DF46385536ECC3865087F9F6A877B1FC7F3E80EA22CA7F91A5D90C52B7143E57").unwrap();assert!(r.validate(m,100000).is_err());r.validate_schema(m,100000,2).unwrap();
 for(k,bad)in [("schema",json!(1)),("hold_point",json!("AFTER_PEEK")),("overlap_policy",json!("NEW_LANE")),("control_contract",json!("V1"))]{let mut x=v.clone();x[k]=bad;assert!(decode::<Ready2>(&serde_json::to_vec(&x).unwrap(),32768).unwrap().common().is_err());}
 let s=scope(10275,0x8000000000000200);let w:Witness=serde_json::from_value(witness_model()).unwrap();let j:Job2=serde_json::from_value(job_model()).unwrap();assert!(j.verify(ID,s,2,Some(&w)).unwrap());
 for(k,bad)in [("job_id",json!("22222222-2222-4333-8444-555555555555")),("source",json!(42)),("object",json!(10163)),("selected_epoch_hex",json!("8000000000000201")),("channel_id",json!(1)),("private_registration_generation",json!("fedcba9876543211")),("effective_gear_revision_at_entry",json!(1)),("work_deadline_monotonic_nanos",json!(1234567891)),("work_operation_id",json!("22222222-2222-4333-8444-555555555555")),("correlation_origin",json!("REQUEST_OR_PEEK")),("revision",json!(1)),("work_observed",json!(false)),("valid_until_millis",json!(1000))]{let mut x=job_model();x[k]=bad;assert!(serde_json::from_value::<Job2>(x).unwrap().verify(ID,s,2,Some(&w)).is_err(),"{k}");}
 let mut partial=job_model();partial.as_object_mut().unwrap().remove("work_operation_id");assert!(serde_json::from_value::<Job2>(partial).unwrap().verify(ID,s,2,Some(&w)).is_err());let mut unknown=job_model();unknown["lease"]=json!("fake");assert!(serde_json::from_value::<Job2>(unknown).is_err());
 let raw=serde_json::to_string(&job_model()).unwrap();let duplicate=raw.replacen('{',"{\"job_id\":\"11111111-2222-4333-8444-555555555555\",",1);assert!(decode::<Job2>(duplicate.as_bytes(),32768).is_err());
 let status=format!("{{\"schema\":2,\"fixture_id\":\"{ID}\",\"state\":\"READY\",\"expires_at_epoch_millis\":1000,\"server\":{{}},\"provider_calls\":1,\"hold\":null,\"timer_owned\":false,\"jobs\":{{\"{ID}\":{raw},\"{ID}\":{raw}}}}}");assert!(decode::<Status2>(status.as_bytes(),32768).is_err());
 let running=json!({"job_id":ID,"state":"RUNNING","source":7,"object":10275,"epoch_hex":"8000000000000200","channel_id":0,"work_observed":false});assert!(!serde_json::from_value::<Job2>(running).unwrap().verify(ID,s,2,None).unwrap());
 let snap:Value=serde_json::from_slice(&fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r445-external-control-v2-snapshot.json")).unwrap()).unwrap();let root=PathBuf::from(snap["evidence"]["root"].as_str().unwrap());let retired:Retirement2=decode(&fs::read(root.join("retirement.json")).unwrap(),32768).unwrap();assert_eq!(retired.schema,2);assert_eq!(retired.state,"TLS_CONTROL_AND_BACKEND_RETIRED");assert!(retired.timer_restored&&retired.world_store_quiescent&&uuid(&retired.fixture_id)&&retired.TLS_port!=0&&retired.control_port!=0&&!retired.reason.is_empty());
}
struct Live{a:Adapter2,c:Option<tls::ModernTlsConnection>,end:Instant,events:Vec<Value>,pending:Option<String>,opened:u32,closed:u32}
impl Live{
 fn event(&mut self,name:&str,s:Scope,value:Value){self.events.push(json!({"event":name,"wall_clock_millis":now().ok(),"scope":s.safe_value(),"data":value}));}
 fn status(&self)->Result<Status2>{let v=self.a.status(self.end)?;require(!v.timer_owned,"v2_no_SQL_timer")?;Ok(v)}
 fn select(&mut self,s:Scope)->Result<gear::Snapshot>{let c=self.c.as_mut().ok_or(err("v2_closed"))?;let roster=c.characters(s.context.key.source_id,s.context.epoch).map_err(|_|err("v2_roster"))?;require(roster.characters.iter().any(|v|v.key==s.context.key),"v2_actual_roster")?;let nav=c.select_character(s.context).map_err(|_|err("v2_select"))?;runner::verify_navigation(&nav,s,app::NavigationPhase::Channels)?;let nav=c.enter_channel(s.channel).map_err(|_|err("v2_channel"))?;runner::verify_navigation(&nav,s,app::NavigationPhase::Lobby)?;let g=runner::verify_gear(&c.equipment(gear::Request::read(s.context)).map_err(|_|err("v2_gear"))?,s)?;self.event("ACTUAL_TLS_SELECTED_GEAR",s,json!({"revision":g.revision,"allflags":g.flags.iter().map(|f|json!({"item":f.item_id,"equipped":f.equipped})).collect::<Vec<_>>()}));Ok(g)}
 fn fresh(&self,s:Scope,ms:u32)->Result<String>{let v=self.a.command("FRESH_READ",&fresh_fields(s,ms),self.end)?;require(v.as_object().is_some_and(|v|v.len()==1),"v2_fresh_shape")?;let id=v["job_id"].as_str().ok_or(err("v2_fresh_id"))?;require(uuid(id),"v2_fresh_id")?;Ok(id.into())}
 fn held(&mut self,s:Scope,revision:i64,ms:u32)->Result<(String,Witness,i64)>{
 let before=self.status()?.provider_calls;let h:Hold2=serde_json::from_value(self.a.command("ARM_HOLD",&[("source_id",s.context.key.source_id.to_string()),("object_id",s.context.key.object_id.to_string())],self.end)?).map_err(|_|err("v2_hold_schema"))?;require(uuid(&h.hold_id)&&h.source==s.context.key.source_id&&h.object==s.context.key.object_id&&!h.entered&&!h.released&&!h.finished&&h.result=="ARMED"&&h.witness()?.is_none(),"v2_arm_before_Work")?;self.pending=Some(h.hold_id.clone());let job=self.fresh(s,ms)?;let until=Instant::now()+Duration::from_secs(3);
 loop{require(Instant::now()<until&&Instant::now()<self.end,"v2_entry_timeout")?;let status=self.status()?;let entry=status.hold.ok_or(err("v2_hold_absent"))?;require(entry.hold_id==h.hold_id,"v2_hold_identity")?;if entry.entered{let w=entry.witness()?.ok_or(err("v2_observation_missing"))?;w.verify(&job,s,revision)?;require(status.provider_calls==before+1&&entry.sql_query_started_epoch_millis>0&&entry.sql_cutoff_exclusive_epoch_millis==-1&&entry.remaining_nanos_at_entry>0&&!entry.released&&!entry.finished&&entry.result=="HOLDING_AFTER_REAL_SQL_AND_RECONCILED_STORE"&&status.jobs.get(&job).is_some_and(|j|j.state=="RUNNING")&&status.jobs.values().filter(|j|j.state=="RUNNING").count()==1,"v2_actual_SQL_reconciled_hold")?;self.event("ACTUAL_SAME_WORK_RECONCILED_SQL_HOLD",s,json!({"hold":entry,"provider_before":before,"provider_after":status.provider_calls,"requested_deadline_ms":ms}));return Ok((job,w,entry.remaining_nanos_at_entry));}thread::sleep(Duration::from_millis(15));}
 }
 fn release(&mut self,s:Scope,w:&Witness,timeout:bool,entry_remaining:i64)->Result<()>{let id=self.pending.as_ref().ok_or(err("v2_pending_hold"))?.clone();let h:Hold2=serde_json::from_value(self.a.command("RELEASE",&[("hold_id",id.clone())],self.end)?).map_err(|_|err("v2_release_schema"))?;require(h.hold_id==id&&h.entered&&h.released&&h.witness()?.as_ref()==Some(w)&&h.backend_remaining_nanos_at_release<=entry_remaining&&h.release_at_epoch_millis>=h.sql_query_started_epoch_millis,"v2_release_same_Work_deadline")?;require(if timeout{h.finished&&h.result=="REJECTED"&&h.backend_remaining_nanos_at_release<=0}else{h.backend_remaining_nanos_at_release>500_000_000},"v2_backend_deadline_distinction")?;self.pending=None;self.event("ACTUAL_SAME_WORK_RELEASE",s,json!({"hold":h,"backend_timeout":timeout}));Ok(())}
 fn terminal(&mut self,id:&str,s:Scope,revision:i64,w:Option<&Witness>,rejected:bool,weapon:i64)->Result<()>{let until=Instant::now()+Duration::from_secs(4);loop{require(Instant::now()<until&&Instant::now()<self.end,"v2_terminal_timeout")?;let st=self.status()?;let j=st.jobs.get(id).ok_or(err("v2_job_missing"))?;if j.verify(id,s,revision,w)?{require(j.state==if rejected{"REJECTED"}else{"COMPLETE"},"v2_terminal_state")?;if !rejected{require(j.weapon_object==Some(weapon),"v2_actual_effective_weapon")?;}self.event("ACTUAL_SAME_WORK_TERMINAL",s,json!({"job":j,"provider_calls":st.provider_calls}));return Ok(())}thread::sleep(Duration::from_millis(15));}}
 fn run(&mut self,p:&runner::Plan)->Result<()>{
 let a=scope(10275,0x8000000000000200);let b=scope(10163,0x8000000000000201);
 let mut c=tls::connect_and_negotiate(p.endpoint,&p.server_name,Some(&p.ca_der),protocol::Hello{request_id:1,min_version:26,max_version:26,supported_capabilities:runner::CAPS,required_capabilities:runner::CAPS,numeric_schema:1},tls::TransportLimits{connect_timeout:Duration::from_secs(2),total_timeout:Duration::from_secs(45),io_poll_interval:Duration::from_millis(25)},tls::Cancellation::new()).map_err(|_|err("v2_TLS_connect"))?;self.opened=1;c.set_exchange_timeout(Duration::from_secs(2)).map_err(|_|err("v2_TLS_limits"))?;let auth=c.authenticate(app::Credentials::new("3333".into(),"3333".into()).map_err(|_|err("v2_credentials"))?).map_err(|_|err("v2_AUTH"))?;require(auth.authorizes_source(7),"v2_AUTH_source")?;self.c=Some(c);let mut g=self.select(a)?;require(g.revision==0&&g.equipped(10304)==Some(true),"v2_original_weapon")?;
 for desired in [false,true]{let c=self.c.as_mut().unwrap();let reply=c.equipment(gear::Request::set(&g,10304,desired)).map_err(|_|err("v2_CAS"))?;let next=runner::verify_gear(&reply,a)?;runner::verify_CAS(&g,&next,10304,desired,reply.changed)?;g=next;self.event("ACTUAL_TLS_CAS",a,json!({"revision":g.revision,"allflags":g.flags.iter().map(|f|json!({"item":f.item_id,"equipped":f.equipped})).collect::<Vec<_>>()}));let(id,w,remaining)=self.held(a,g.revision,8000)?;self.release(a,&w,false,remaining)?;self.terminal(&id,a,g.revision,Some(&w),false,if desired{10304}else{0})?;}
 let(id,w,remaining)=self.held(a,2,8000)?;let nav=self.c.as_mut().unwrap().return_characters().map_err(|_|err("v2_BACK"))?;runner::verify_navigation(&nav,a,app::NavigationPhase::Characters)?;
 match self.c.as_mut().unwrap().characters(7,b.context.epoch){Err(tls::TransportError::CharactersRejected(app::CharacterFailure::BackendUnavailable))=>self.event("ACTUAL_BACK_HELD_SESSION_GATE_BUSY",b,json!({"CHAR_RESULT":"BackendUnavailable","status":2,"new_owner_admitted":false,"old_Work":w})),_=>return Err(err("v2_expected_single_work_slot_BUSY"))}
 self.release(a,&w,false,remaining)?;self.terminal(&id,a,2,Some(&w),true,-1)?;
 // Wait for actual retirement with bounded read-only roster requests; no new lane.
 let until=Instant::now()+Duration::from_secs(3);loop{match self.c.as_mut().unwrap().characters(7,b.context.epoch){Ok(roster)=>{require(roster.characters.iter().any(|v|v.key==b.context.key),"v2_retired_roster")?;break},Err(tls::TransportError::CharactersRejected(app::CharacterFailure::BackendUnavailable))=>{require(Instant::now()<until,"v2_Work_not_retired")?;thread::sleep(Duration::from_millis(20));},_=>return Err(err("v2_serial_roster"))}}
 let g=self.select(b)?;require(g.revision==0,"v2_reselect_revision")?;let id=self.fresh(b,8000)?;self.terminal(&id,b,0,None,false,10252)?;
 let(id,w,remaining)=self.held(b,0,500)?;let until=Instant::now()+Duration::from_secs(3);loop{require(Instant::now()<until,"v2_timeout_not_finished")?;let st=self.status()?;let h=st.hold.ok_or(err("v2_hold_absent"))?;require(h.witness()?.as_ref()==Some(&w),"v2_timeout_same_Work")?;if h.finished{require(!h.released&&h.result=="REJECTED"&&h.sql_cutoff_exclusive_epoch_millis==-1,"v2_backend_timeout_no_SQL_expiry")?;self.event("ACTUAL_WORK_BACKEND_DEADLINE_BEFORE_RELEASE",b,json!({"hold":h,"SQL_timer":false}));break;}thread::sleep(Duration::from_millis(15));}
 self.release(b,&w,true,remaining)?;self.terminal(&id,b,0,Some(&w),true,-1)?;let final_status=self.status()?;require(final_status.provider_calls==5&&final_status.jobs.len()==5,"v2_bounded_actual_work_count")?;Ok(())
 }
 fn finish(&mut self)->Vec<Fault>{let mut errors=Vec::new();let end=Instant::now()+Duration::from_secs(4);if let Some(mut c)=self.c.take(){if c.close().is_ok(){self.closed+=1}else{errors.push(err("v2_TLS_close"))}drop(c)}if let Some(h)=self.pending.take(){if self.a.command("RELEASE",&[("hold_id",h)],end).is_err(){errors.push(err("v2_final_release"))}}if self.a.command("TIMER_CLEAR",&[],end).is_err(){errors.push(err("v2_timer_clear"))}if self.a.command("SHUTDOWN",&[],end).is_err(){errors.push(err("v2_SHUTDOWN"))}errors}
}
#[test]#[ignore="Explicit schema2 Modern-owned fresh fixture only"]fn actual_v2_same_Work_CAS_and_selected_lifecycle(){
 let path=PathBuf::from(std::env::var("LITO_R445_READY").expect("explicit READY"));let runtime=path.parent().unwrap();let project=Path::new(env!("CARGO_MANIFEST_DIR"));let snap:Value=serde_json::from_slice(&fs::read(project.join("logs/continuation-20261003/r445-external-control-v2-snapshot.json")).unwrap()).unwrap();let manifest=hash(snap["candidate"]["manifest_sha256"].as_str().unwrap()).unwrap();assert_eq!(manifest,hash("C88CBCC80A512A2F17766B72872D388EFC71D66C1CDBC3A46E5CDA69C7B1C1BE").unwrap());let(a,p)=Adapter2::bind(&path,runtime,manifest).expect("strict v2 ready/owner/PKI");let mut l=Live{a,c:None,end:Instant::now()+Duration::from_secs(45),events:Vec::new(),pending:None,opened:0,closed:0};let result=l.run(&p);let errors=l.finish();let okay=result.is_ok()&&errors.is_empty()&&l.opened==1&&l.closed==1;
 let report=json!({"state":if okay{"RUST_V2_SAME_WORK_PASSED_PENDING_RETIREMENT"}else{"RUST_V2_SAME_WORK_FAILED"},"schema":2,"fixture_id":l.a.transport.ready.fixture_id,"candidate_manifest_sha256":snap["candidate"]["manifest_sha256"],"events":l.events,"failure":result.err(),"cleanup_errors":errors,"TLS_opened":l.opened,"TLS_close_notify":l.closed,"full_recipe_rerun":false,"R442_matrix_rerun":false,"SQL_timer_armed":false,"overlap_intentionally_unavailable":true,"new_owner_admitted_during_hold":false,"renderer_LOADED":false,"GUI":0});fs::write(runtime.join("modern-rust-v2-report.json"),serde_json::to_vec_pretty(&report).unwrap()).unwrap();assert!(okay,"v2 live failed; safe report retained");
}
